import requests
import pandas as pd

def task_func(url):
    try:
        response = requests.get(url)
    except requests.RequestException:
        raise SystemError("Request failed due to a system error.")
    try:
        data = response.json()
    except ValueError as exc:
        # Propagate JSON decode errors
        raise exc
    # If the JSON is None, replace it with an empty list.
    if data is None:
        data = []
    return pd.DataFrame(data)

